contracts/RiskSteward/CollateralFactorsR.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { RiskParameterUpdate } from "./Interfaces/IRiskOracle.sol";
import { ICorePoolVToken } from "../interfaces/ICorePoolVToken.sol";
import { ICorePoolComptroller } from "../interfaces/ICorePoolComptroller.sol";
import { IIsolatedPoolsComptroller } from "../interfaces/IIsolatedPoolsComptroller.sol";
import { IRiskStewardReceiver } from "./Interfaces/IRiskStewardReceiver.sol";
import { AccessControlledV8 } from "../Governance/AccessControlledV8.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";
import { IRiskSteward } from "./Interfaces/IRiskSteward.sol";

/**
 * @title CollateralFactorsRiskSteward
 * @author Venus
 * @notice Contract that can update collateral factors and liquidation thresholds received from `RiskStewardReceiver`.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */
contract CollateralFactorsRiskSteward is IRiskSteward, AccessControlledV8 {
    /// @dev Max basis points i.e., 100%
    uint256 private constant MAX_BPS = 10000;

    /**
     * @notice The update type for collateral factor and liquidation threshold.
     */
    string public constant COLLATERAL_FACTORS = "collateralFactors";

    /**
     * @notice The update type key for collateral factors (keccak256 hash of COLLATERAL_FACTORS)
     */
    bytes32 public constant COLLATERAL_FACTORS_KEY = keccak256(bytes(COLLATERAL_FACTORS));

    /**
     * @notice Address of the BNB Core Pool Comptroller.
     * @dev This comptroller is specific to the BNB Core Pool, which uses a different ABI
     *      than isolated pools. It is used solely to detect and handle BNB Core Pool
     *      markets, and would not be used for remote-chain (isolated pool) deployments.
     */
    ICorePoolComptroller public immutable CORE_POOL_COMPTROLLER;

    /**
     * @notice Address of the `RiskStewardReceiver` used to validate and dispatch incoming updates.
     */
    IRiskStewardReceiver public immutable RISK_STEWARD_RECEIVER;

    /**
     * @notice The safe delta threshold in basis points. Updates within this delta are considered safe and
     *         can be executed without a timelock. Updates exceeding this delta require a timelock.
     */
    uint256 public safeDeltaBps;

    /**
     * @dev Storage gap for upgradeability.
     */
    uint256[49] private __gap;

    /**
     * @notice Emitted when collateral factors are updated.
     */
    event CollateralFactorsUpdated(
        uint256 indexed updateId,
        address indexed market,
        uint256 newCollateralFactor,
        uint256 newLiquidationThreshold
    );

    /**
     * @notice Emitted when the safe delta bps is updated.
     */
    event SafeDeltaBpsUpdated(uint256 indexed oldSafeDeltaBps, uint256 indexed newSafeDeltaBps);

    /**
     * @notice Thrown when a `safeDeltaBps` value is greater than `MAX_BPS`.
     */
    error InvalidSafeDeltaBps();

    /**
     * @notice Thrown when Core Pool Comptroller.setCollateralFactor fails.
     */
    error SetCollateralFactorFailed(uint256 errorCode);

    /**
     * @notice Thrown when an update type that is not supported is operated on.
     */
    error UnsupportedUpdateType();

    /**
     * @notice Thrown when the update is not coming from the `RiskStewardReceiver`.
     */
    error OnlyRiskStewardReceiver();

    /**
     * @notice Thrown when trying to renounce ownership.
     */
    error RenounceOwnershipNotAllowed();

    /**
     * @notice Thrown when the two uint256 data length is invalid
     */
    error InvalidTwoUintLength();

    /**
     * @notice Sets the immutable `CORE_POOL_COMPTROLLER` and `RISK_STEWARD_RECEIVER` addresses and disables initializers.
     * @param corePoolComptroller_ The address of the Core Pool Comptroller
     * @param riskStewardReceiver_ The address of the `RiskStewardReceiver`
     * @custom:error Throws ZeroAddressNotAllowed if any of the addresses are zero
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(address corePoolComptroller_, address riskStewardReceiver_) {
        ensureNonzeroAddress(riskStewardReceiver_);
        CORE_POOL_COMPTROLLER = ICorePoolComptroller(corePoolComptroller_);
        RISK_STEWARD_RECEIVER = IRiskStewardReceiver(riskStewardReceiver_);
        _disableInitializers();
    }

    /**
     * @notice Initializes the contract as ownable and access controlled.
     * @param accessControlManager_ The address of the access control manager
     */
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
    }

    /**
     * @notice Sets the safe delta bps.
     * @param safeDeltaBps_ The new safe delta bps
     * @custom:event Emits SafeDeltaBpsUpdated with the old and new safe delta bps
     * @custom:error Throws InvalidSafeDeltaBps if the safe delta bps is greater than MAX_BPS
     * @custom:access Controlled by AccessControlManager
     */
    function setSafeDeltaBps(uint256 safeDeltaBps_) external {
        _checkAccessAllowed("setSafeDeltaBps(uint256)");
        if (safeDeltaBps_ > MAX_BPS) {
            revert InvalidSafeDeltaBps();
        }
        emit SafeDeltaBpsUpdated(safeDeltaBps, safeDeltaBps_);
        safeDeltaBps = safeDeltaBps_;
    }

    /**
     * @notice Checks if an update is safe for direct execution (no timelock required).
     * @param update The update to check.
     * @return True if update is safe for direct execution, false if timelock is required
     * @custom:error Throws UnsupportedUpdateType if the update type is not supported
     */
    function isSafeForDirectExecution(RiskParameterUpdate calldata update) external view returns (bool) {
        // eMode-style updates always require timelock (not safe for direct execution)
        if (update.poolId != 0) return false;

        if (update.updateTypeKey == COLLATERAL_FACTORS_KEY) {
            address comptroller = ICorePoolVToken(update.market).comptroller();

            (uint256 newCF, uint256 newLT) = _decodeAbiEncodedTwoUint256(update.newValue);
            (uint256 currCF, uint256 currLT) = _getCurrentCollateralFactors(comptroller, update.market);

            // If current values are zero, update always requires timelock
            if (currCF == 0 || currLT == 0) return false;

            return _isWithinSafeDelta(newCF, currCF) && _isWithinSafeDelta(newLT, currLT);
        }

        revert UnsupportedUpdateType();
    }

    /**
     * @notice Applies a collateral parameter update from the `RiskStewardReceiver`.
     *         Delta validation and timelock checks are already performed by `RiskStewardReceiver` before execution.
     * @param update RiskParameterUpdate update to apply
     * @custom:access Only callable by the `RiskStewardReceiver`
     * @custom:event Emits CollateralFactorsUpdated with updateId
     * @custom:error Throws OnlyRiskStewardReceiver if the sender is not the `RiskStewardReceiver`
     * @custom:error Throws UnsupportedUpdateType if the update type is not supported
     */
    function applyUpdate(RiskParameterUpdate calldata update) external {
        if (msg.sender != address(RISK_STEWARD_RECEIVER)) {
            revert OnlyRiskStewardReceiver();
        }

        address comptroller = ICorePoolVToken(update.market).comptroller();
        uint96 poolId = update.poolId;

        if (update.updateTypeKey == COLLATERAL_FACTORS_KEY) {
            _updateCollateralFactors(update.updateId, comptroller, update.market, poolId, update.newValue);
        } else {
            revert UnsupportedUpdateType();
        }
    }

    /**
     * @notice Updates the collateral factors for the given market.
     * @dev Updates both collateral factor and liquidation threshold together (same setter).
     * @param updateId The update ID from the Risk Oracle
     * @param comptroller The comptroller address
     * @param market The market to update the collateral factors for
     * @param poolId The pool identifier for eMode updates (0 for regular market updates)
     * @param newValue Encoded new collateral factors: `abi.encode(uint256 newCollateralFactor, uint256 newLiquidationThreshold)`
     * @custom:event Emits CollateralFactorsUpdated with updateId
     */
    function _updateCollateralFactors(
        uint256 updateId,
        address comptroller,
        address market,
        uint96 poolId,
        bytes memory newValue
    ) internal {
        (uint256 newCollateralFactor, uint256 newLiquidationThreshold) = abi.decode(newValue, (uint256, uint256));

        if (comptroller == address(CORE_POOL_COMPTROLLER)) {
            uint256 errorCode = ICorePoolComptroller(comptroller).setCollateralFactor(
                poolId,
                market,
                newCollateralFactor,
                newLiquidationThreshold
            );
            if (errorCode != 0) revert SetCollateralFactorFailed(errorCode);
        } else {
            if (poolId != 0) revert UnsupportedUpdateType();

            IIsolatedPoolsComptroller(comptroller).setCollateralFactor(
                market,
                newCollateralFactor,
                newLiquidationThreshold
            );
        }

        emit CollateralFactorsUpdated(updateId, market, newCollateralFactor, newLiquidationThreshold);
    }

    /**
     * @notice Returns the current collateral factors for a market on a given comptroller.
     * @dev Returns both collateral factor and liquidation threshold (updated together via the same setter).
     *      For core pool, uses eMode-specific getter which handles poolId == 0 as regular market.
     * @param comptroller The comptroller address
     * @param market The market whose collateral factors are being queried
     * @return currentCollateralFactor The current collateral factor
     * @return currentLiquidationThreshold The current liquidation threshold
     */
    function _getCurrentCollateralFactors(
        address comptroller,
        address market
    ) internal view returns (uint256 currentCollateralFactor, uint256 currentLiquidationThreshold) {
        if (comptroller == address(CORE_POOL_COMPTROLLER)) {
            (, currentCollateralFactor, , currentLiquidationThreshold, , , ) = ICorePoolComptroller(comptroller)
                .markets(market);
        } else {
            (, currentCollateralFactor, currentLiquidationThreshold) = IIsolatedPoolsComptroller(comptroller).markets(
                market
            );
        }
    }

    /**
     * @notice Checks if the difference between new and current values is within the safe delta threshold.
     * @param newValue The new value to check
     * @param currentValue The current value to compare against
     * @return True if the difference is within the safe delta, false otherwise
     */
    function _isWithinSafeDelta(uint256 newValue, uint256 currentValue) internal view returns (bool) {
        uint256 diff = newValue > currentValue ? newValue - currentValue : currentValue - newValue;
        uint256 maxDiff = (safeDeltaBps * currentValue) / MAX_BPS;
        return diff <= maxDiff;
    }

    /**
     * @notice Decodes ABI-encoded bytes into two uint256 values.
     * @dev Expects exactly 64 bytes as produced by abi.encode(uint256,uint256).
     * @param data ABI-encoded (uint256, uint256) payload
     * @return a First uint256
     * @return b Second uint256
     */
    function _decodeAbiEncodedTwoUint256(bytes memory data) internal pure returns (uint256 a, uint256 b) {
        if (data.length != 64) {
            revert InvalidTwoUintLength();
        }

        (a, b) = abi.decode(data, (uint256, uint256));
    }

    /**
     * @notice Disables `renounceOwnership` function.
     * @custom:error Throws RenounceOwnershipNotAllowed
     */
    function renounceOwnership() public pure override {
        revert RenounceOwnershipNotAllowed();
    }
}

contracts/RiskSteward/DestinationSteward.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { OwnableUpgradeable } from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { RiskParameterUpdate } from "./Interfaces/IRiskOracle.sol";
import { IRiskSteward } from "./Interfaces/IRiskSteward.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";
import { AccessControlledV8 } from "../Governance/AccessControlledV8.sol";
import { IIsolatedPoolsComptroller } from "../interfaces/IIsolatedPoolsComptroller.sol";
import { OAppUpgradeable, Origin } from "@layerzerolabs/oapp-evm-upgradeable/contracts/oapp/OAppUpgradeable.sol";

/**
 * @title DestinationStewardReceiver
 * @author Venus
 * @notice Destination‑chain contract that receives bridged updates from `RiskStewardReceiver` via LayerZero,
 *         enforces a fixed remote delay, and then executes the updates on the configured `IRiskSteward` contracts.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */
contract DestinationStewardReceiver is AccessControlledV8, OAppUpgradeable {
    /**
     * @notice Local status of an update on the destination chain
     */
    enum UpdateStatus {
        None,
        Pending,
        Executed,
        Rejected
    }

    /**
     * @notice Configuration for a risk parameter update type on the destination chain.
     * @param active Whether this update type configuration is currently active
     * @param debounce Minimum delay between consecutive executions for the same (updateType, market) pair
     * @param riskSteward Address of the risk steward contract responsible for processing this update type
     */
    struct RiskParamConfig {
        bool active;
        uint256 debounce;
        address riskSteward;
    }

    /**
     * @notice Destination-side storage for a bridged risk parameter update.
     * @param update The full risk parameter update payload received from the source chain
     * @param status Current local status of the bridged update (Pending, Executed, Rejected)
     * @param arrivalTime Timestamp when the update was received on this chain
     * @param executor Address of the executor who executed this update on the destination (address(0) if not executed yet)
     * @dev Unlock time is derived as `arrivalTime + REMOTE_DELAY` instead of being stored separately.
     */
    struct DestinationUpdate {
        RiskParameterUpdate update;
        UpdateStatus status;
        uint256 arrivalTime;
        address executor;
    }

    /**
     * @notice Time before a bridged update is considered stale on the destination chain
     */
    uint256 public constant REMOTE_UPDATE_EXPIRATION_TIME = 2 days;

    /**
     * @notice Fixed delay before a bridged update can be executed on the destination chain
     */
    uint256 public constant REMOTE_DELAY = 6 hours;

    /**
     * @notice Source chain LayerZero endpoint ID
     */
    uint32 public immutable LAYER_ZERO_EID;

    /**
     * @notice Mapping of supported risk configurations per update type (hashed updateType string)
     */
    mapping(bytes32 => RiskParamConfig) public riskParameterConfigs;

    /**
     * @notice Master storage of all bridged updates by update ID
     */
    mapping(uint256 updateId => DestinationUpdate) public updates;

    /**
     * @notice Mapping from (updateType, market) to currently registered remote update ID
     */
    mapping(bytes32 => mapping(address market => uint256)) public lastRegisteredUpdate;

    /**
     * @notice Track last executed update timestamp per (updateType, market)
     */
    mapping(bytes32 => mapping(address market => uint256)) public lastExecutedAt;

    /**
     * @notice Mapping from executor address to whitelist status
     */
    mapping(address => bool) public whitelistedExecutors;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[45] private __gap;

    /**
     * @notice Emitted when a risk parameter config is updated for an update type
     */
    event RiskParameterConfigUpdated(
        bytes32 indexed updateTypeHash,
        string updateType,
        address indexed previousRiskSteward,
        address indexed riskSteward,
        uint256 previousDebounce,
        uint256 debounce,
        bool previousActive,
        bool active
    );

    /**
     * @notice Emitted when a bridged update is registered on the destination
     */
    event RemoteUpdateRegistered(
        uint256 indexed updateId,
        uint256 arrivalTime,
        string updateType,
        address indexed market
    );

    /**
     * @notice Emitted when a new bridged update arrives but a pending update is already registered for the same (updateType, market).
     */
    event RegisteredPendingUpdateExist(
        uint256 indexed updateId,
        uint256 arrivalTime,
        string updateType,
        address indexed market
    );

    /**
     * @notice Emitted when a duplicate bridged update (same updateId) is received.
     */
    event DuplicateUpdateReceived(
        uint256 indexed updateId,
        uint256 arrivalTime,
        string updateType,
        address indexed market
    );

    /**
     * @notice Emitted when a bridged update is executed on the destination
     */
    event RemoteUpdateExecuted(uint256 indexed updateId);

    /**
     * @notice Emitted when an executor status is set on the destination
     */
    event ExecutorStatusUpdated(address indexed executor, bool previousApproved, bool indexed approved);

    /**
     * @notice Emitted when a risk parameter config active status is updated
     */
    event ConfigActiveUpdated(
        bytes32 indexed updateTypeHash,
        string updateType,
        bool previousActive,
        bool indexed active
    );

    /**
     * @notice Emitted when an update is rejected on the destination
     */
    event UpdateRejected(uint256 indexed updateId);

    /**
     * @notice Emitted when the remote delay is set in the constructor
     */
    event RemoteDelaySet(uint256 remoteDelay);

    /**
     * @notice Thrown when trying to operate on an update that was never registered
     */
    error UpdateNotFound();

    /**
     * @notice Thrown when trying to execute an update before its unlock time
     */
    error UpdateNotUnlocked();

    /**
     * @notice Thrown when config for an update type is not active or not configured
     */
    error ConfigNotActive();

    /**
     * @notice Thrown when a bridged update has expired on the destination
     */
    error UpdateIsExpired();

    /**
     * @notice Thrown when the debounce period hasn't passed for applying an update to a specific market / update type
     */
    error UpdateTooFrequent();

    /**
     * @notice Thrown when an empty update type string is provided
     */
    error InvalidUpdateType();

    /**
     * @notice Thrown when an update type is not supported
     */
    error UnsupportedUpdateType();

    /**
     * @notice Thrown when a debounce value of 0 is set
     */
    error InvalidDebounce();

    /**
     * @notice Thrown when an address is not a whitelisted executor
     */
    error NotAnExecutor();

    /**
     * @notice Modifier that ensures only whitelisted executors can call the function
     * @custom:error NotAnExecutor if the caller is not a whitelisted executor
     */
    modifier onlyWhitelistedExecutors() {
        if (!whitelistedExecutors[msg.sender]) {
            revert NotAnExecutor();
        }
        _;
    }

    /**
     * @notice Disables initializers and sets immutable values.
     * @param endpoint_ Local LayerZero endpoint on this chain
     * @param layerZeroEid_ LayerZero endpoint ID for this destination chain
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(address endpoint_, uint32 layerZeroEid_) OAppUpgradeable(endpoint_) {
        _disableInitializers();
        ensureNonzeroAddress(endpoint_);
        LAYER_ZERO_EID = layerZeroEid_;
        emit RemoteDelaySet(REMOTE_DELAY);
    }

    /**
     * @notice Initializes the contract with the Access Control Manager and owner.
     * @param accessControlManager_ The address of the access control manager
     * @param delegate_ The owner (and LayerZero delegate) of this contract
     */
    function initialize(address accessControlManager_, address delegate_) external initializer {
        __AccessControlled_init(accessControlManager_);
        __OApp_init(delegate_);
    }

    /**
     * @notice Sets the risk parameter config for a given update type on the destination chain.
     * @param updateType The type of update to configure (e.g., "supplyCap", "borrowCap")
     * @param riskSteward The address for the risk steward contract responsible for processing the update
     * @param debounce The debounce period for updates of this type on the destination (anti‑DoS)
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits RiskParameterConfigUpdated (with previousTimelock and timelock always emitted as 0)
     * @custom:error InvalidUpdateType if the update type string is empty
     * @custom:error InvalidDebounce if the debounce is 0
     */
    function setRiskParameterConfig(string calldata updateType, address riskSteward, uint256 debounce) external {
        _checkAccessAllowed("setRiskParameterConfig(string,address,uint256)");
        ensureNonzeroAddress(riskSteward);

        if (bytes(updateType).length == 0) {
            revert InvalidUpdateType();
        }

        if (debounce == 0) {
            revert InvalidDebounce();
        }

        bytes32 key = keccak256(bytes(updateType));
        RiskParamConfig storage previousConfig = riskParameterConfigs[key];

        riskParameterConfigs[key] = RiskParamConfig({ active: true, debounce: debounce, riskSteward: riskSteward });

        emit RiskParameterConfigUpdated(
            key,
            updateType,
            previousConfig.riskSteward,
            riskSteward,
            previousConfig.debounce,
            debounce,
            previousConfig.active,
            true
        );
    }

    /**
     * @notice Sets the active status of a risk parameter config
     * @param updateType The type of update to configure
     * @param active The active status to set
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits ConfigActiveUpdated with the update type hash, update type, previous active status, and the active status
     * @custom:error Throws UnsupportedUpdateType if the update type is not supported
     */
    function setConfigActive(string calldata updateType, bool active) external {
        _checkAccessAllowed("setConfigActive(string,bool)");
        bytes32 key = keccak256(bytes(updateType));

        if (riskParameterConfigs[key].riskSteward == address(0)) {
            revert UnsupportedUpdateType();
        }

        bool previousActive = riskParameterConfigs[key].active;
        if (previousActive == active) {
            return;
        }

        riskParameterConfigs[key].active = active;
        emit ConfigActiveUpdated(key, updateType, previousActive, active);
    }

    /**
     * @notice Sets the whitelist status of an executor on the destination chain.
     * @param executor The address of the executor
     * @param approved The whitelist status to set (true to whitelist, false to remove)
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits ExecutorStatusUpdated with the executor address, previous approval status, and new approval status
     */
    function setWhitelistedExecutor(address executor, bool approved) external {
        _checkAccessAllowed("setWhitelistedExecutor(address,bool)");
        ensureNonzeroAddress(executor);
        bool previousApproved = whitelistedExecutors[executor];
        if (previousApproved == approved) {
            return;
        }

        whitelistedExecutors[executor] = approved;
        emit ExecutorStatusUpdated(executor, previousApproved, approved);
    }

    /**
     * @notice Executes a bridged update after its remote delay has passed.
     * @param updateId The bridged update ID to execute
     * @custom:access Only whitelisted executors can execute updates
     * @custom:event Emits RemoteUpdateExecuted with the executed update ID
     * @custom:error NotAnExecutor if the caller is not a whitelisted executor
     * @custom:error ConfigNotActive if the configuration for the update type is not active
     * @custom:error UpdateNotFound if the update is not pending for the given (updateType, market)
     * @custom:error UpdateNotUnlocked if the remote delay has not elapsed
     * @custom:error UpdateIsExpired if the bridged update has expired on the destination
     * @custom:error UpdateTooFrequent if the debounce period has not passed since the last execution
     */
    function executeUpdate(uint256 updateId) external onlyWhitelistedExecutors {
        DestinationUpdate storage destUpdate = updates[updateId];
        RiskParameterUpdate memory update = destUpdate.update;
        bytes32 updateTypeKey = update.updateTypeKey;
        RiskParamConfig storage config = riskParameterConfigs[updateTypeKey];
        uint256 currentTime = block.timestamp;

        if (!config.active) {
            revert ConfigNotActive();
        }

        if (destUpdate.status != UpdateStatus.Pending) {
            revert UpdateNotFound();
        }

        if (currentTime < destUpdate.arrivalTime + REMOTE_DELAY) {
            revert UpdateNotUnlocked();
        }

        if (update.timestamp + REMOTE_UPDATE_EXPIRATION_TIME < currentTime) {
            revert UpdateIsExpired();
        }

        // Destination-side debounce based on last execution for this (updateType, market)
        uint256 lastExecutionTime = lastExecutedAt[updateTypeKey][update.market];
        if (lastExecutionTime != 0 && (lastExecutionTime + config.debounce > currentTime)) {
            revert UpdateTooFrequent();
        }

        lastExecutedAt[updateTypeKey][update.market] = currentTime;
        destUpdate.status = UpdateStatus.Executed;
        destUpdate.executor = msg.sender;

        IRiskSteward(config.riskSteward).applyUpdate(update);

        emit RemoteUpdateExecuted(updateId);
    }

    /**
     * @notice Rejects a registered remote update on the destination chain.
     * @param updateId The oracle update ID of the update to reject
     * @custom:access Only whitelisted executors can reject updates
     * @custom:event Emits UpdateRejected with the rejected update ID
     * @custom:error NotAnExecutor if the caller is not a whitelisted executor
     * @custom:error UpdateNotFound if there is no pending update with the given ID
     */
    function rejectUpdate(uint256 updateId) external onlyWhitelistedExecutors {
        DestinationUpdate storage destUpdate = updates[updateId];

        if (destUpdate.status != UpdateStatus.Pending) {
            revert UpdateNotFound();
        }

        destUpdate.status = UpdateStatus.Rejected;
        emit UpdateRejected(updateId);
    }

    /**
     * @notice Returns executable updates for a given update type and comptroller.
     * @param updateType The human‑readable identifier of the update type to filter by
     * @param comptroller The address of the Isolated Pools Comptroller that manages the markets
     * @return executableUpdates Array of update IDs that are ready to be executed
     */
    function getExecutableUpdates(
        string calldata updateType,
        address comptroller
    ) external view returns (uint256[] memory executableUpdates) {
        bytes32 updateTypeKey = keccak256(bytes(updateType));
        address[] memory markets = IIsolatedPoolsComptroller(comptroller).getAllMarkets();
        uint256 maxUpdates = markets.length;
        uint256[] memory tempArray = new uint256[](maxUpdates);
        uint256 count = 0;
        RiskParamConfig storage config = riskParameterConfigs[updateTypeKey];

        if (!config.active) return new uint256[](0);

        for (uint256 i = 0; i < maxUpdates; ++i) {
            address market = markets[i];
            uint256 registeredUpdateId = lastRegisteredUpdate[updateTypeKey][market];
            DestinationUpdate storage destUpdate = updates[registeredUpdateId];

            if (!_checkPendingUpdate(registeredUpdateId)) continue;

            // Validate Remote Delay
            if (block.timestamp < destUpdate.arrivalTime + REMOTE_DELAY) continue;

            // Debounce: skip if last execution for this (updateType, market) is too recent
            uint256 lastExecutionTime = lastExecutedAt[updateTypeKey][market];
            if (lastExecutionTime != 0 && (lastExecutionTime + config.debounce > block.timestamp)) continue;

            tempArray[count] = registeredUpdateId;
            count++;
        }

        executableUpdates = new uint256[](count);
        for (uint256 i = 0; i < count; ++i) {
            executableUpdates[i] = tempArray[i];
        }
    }

    /**
     * @notice Returns the risk parameter configuration for a given update type
     * @param updateType The human-readable identifier of the update type
     * @return The risk parameter configuration
     */
    function getRiskParameterConfig(string calldata updateType) external view returns (RiskParamConfig memory) {
        bytes32 key = keccak256(bytes(updateType));
        return riskParameterConfigs[key];
    }

    /**
     * @notice Returns the registered update for a given update type and market
     * @param updateType The human-readable identifier of the update type
     * @param market The address of the market
     * @return The registered update
     */
    function getRegisteredUpdate(
        string calldata updateType,
        address market
    ) external view returns (DestinationUpdate memory) {
        bytes32 key = keccak256(bytes(updateType));
        uint256 updateId = lastRegisteredUpdate[key][market];
        return updates[updateId];
    }

    /**
     * @notice Returns the last executed timestamp for a given update type and market
     * @param updateType The human-readable identifier of the update type
     * @param market The address of the market
     * @return The last executed timestamp
     */
    function getLastExecutedAt(string calldata updateType, address market) external view returns (uint256) {
        bytes32 key = keccak256(bytes(updateType));
        return lastExecutedAt[key][market];
    }

    /**
     * @dev Overrides OwnableUpgradeable and Ownable2StepUpgradeable to resolve
     *      the multiple inheritance ownership transfer conflict.
     */
    function transferOwnership(
        address newOwner
    ) public override(OwnableUpgradeable, Ownable2StepUpgradeable) onlyOwner {
        Ownable2StepUpgradeable.transferOwnership(newOwner);
    }

    /**
     * @dev Internal hook to finalize ownership transfer, resolving the
     *      OwnableUpgradeable and Ownable2StepUpgradeable inheritance conflict.
     */
    function _transferOwnership(address newOwner) internal override(OwnableUpgradeable, Ownable2StepUpgradeable) {
        Ownable2StepUpgradeable._transferOwnership(newOwner);
    }

    /**
     * @notice Internal LayerZero receive hook that handles bridged updates from the source-chain `RiskStewardReceiver`.
     * @dev Emits `DuplicateUpdateReceived`, `RegisteredPendingUpdateExist`, or `RemoteUpdateRegistered`
     *      depending on whether the update ID was already seen or a non‑expired pending update exists.
     * @param payload Encoded `RiskParameterUpdate` sent from the source chain
     */
    function _lzReceive(Origin calldata, bytes32, bytes calldata payload, address, bytes calldata) internal override {
        RiskParameterUpdate memory update = abi.decode(payload, (RiskParameterUpdate));
        uint256 newId = update.updateId;
        uint256 arrivalTime = block.timestamp;

        // If this update ID was already stored, treat as a duplicate and do not overwrite
        if (updates[newId].status != UpdateStatus.None) {
            emit DuplicateUpdateReceived(newId, arrivalTime, update.updateType, update.market);
            return;
        }

        // If already an update in Process do not override the registered update
        uint256 currentRegisteredId = lastRegisteredUpdate[update.updateTypeKey][update.market];
        if (_checkPendingUpdate(currentRegisteredId)) {
            emit RegisteredPendingUpdateExist(currentRegisteredId, arrivalTime, update.updateType, update.market);
            return;
        }

        DestinationUpdate storage destUpdate = updates[newId];
        destUpdate.update = update;
        destUpdate.status = UpdateStatus.Pending;
        destUpdate.arrivalTime = arrivalTime;
        lastRegisteredUpdate[update.updateTypeKey][update.market] = newId;
        emit RemoteUpdateRegistered(newId, arrivalTime, update.updateType, update.market);
    }

    /**
     * @notice Checks if there is a pending, non‑expired registered update for the same (updateType, market).
     * @param currentRegisteredId The currently registered update ID for the same (updateType, market)
     * @return True if there is a pending, non‑expired registered update for the same (updateType, market), false otherwise
     */
    function _checkPendingUpdate(uint256 currentRegisteredId) internal view returns (bool) {
        if (currentRegisteredId == 0) return false; // no registered update

        DestinationUpdate storage current = updates[currentRegisteredId];

        if (current.status != UpdateStatus.Pending) return false;

        // Check expiration
        return current.update.timestamp + REMOTE_UPDATE_EXPIRATION_TIME > block.timestamp;
    }
}

contracts/RiskSteward/Interfaces/IRiskOr.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

/**
 * @notice Struct representing a risk parameter update published by the Risk Oracle
 * @param referenceId External reference ID, potentially linking to a document or off-chain data
 * @param updateId Unique identifier for this specific update
 * @param market Address of the market for which the parameter update applies
 * @param updateType Classification of the update type for validation purposes (human-readable)
 * @param updateTypeKey Keccak256 hash of updateType for efficient comparisons
 * @param newValue Encoded new value of the risk parameter, flexible for various data types
 * @param previousValue Previous value of the parameter for historical comparison
 * @param timestamp Block timestamp when the update was published
 * @param publisher Address of the account that published this update
 * @param poolId Pool identifier for eMode-style collateral configuration (0 for regular markets)
 * @param destLzEid LayerZero endpoint ID of the destination chain (0 for local execution)
 * @param additionalData Additional metadata or data associated with the update
 */
struct RiskParameterUpdate {
    string referenceId;
    uint256 updateId;
    address market;
    string updateType;
    bytes32 updateTypeKey;
    bytes newValue;
    bytes previousValue;
    uint256 timestamp;
    address publisher;
    uint96 poolId;
    uint32 destLzEid;
    bytes additionalData;
}

/**
 * @title IRiskOracle
 * @author Venus
 * @notice Interface for Risk Oracle contract that manages and publishes risk parameter updates
 */
interface IRiskOracle {
    /**
     * @notice Returns the update type string at the given index in the allUpdateTypes array
     * @param index The index in the allUpdateTypes array
     * @return The update type string at the specified index
     */
    function allUpdateTypes(uint256 index) external view returns (string memory);

    /**
     * @notice Returns the total number of update types in the allUpdateTypes array
     * @return The length of the allUpdateTypes array
     */
    function allUpdateTypesLength() external view returns (uint256);

    /**
     * @notice Returns all update types in the allUpdateTypes array
     * @return An array of all update type strings
     */
    function getAllUpdateTypes() external view returns (string[] memory);

    /**
     * @notice Checks if a given update type is currently active
     * @param updateType The update type string to check
     * @return True if the update type is active, false otherwise
     */
    function activeUpdateTypes(string memory updateType) external view returns (bool);

    /**
     * @notice Checks if an address is authorized to publish updates
     * @param sender The address to check for authorization
     * @return True if the address is authorized, false otherwise
     */
    function authorizedSenders(address sender) external view returns (bool);

    /**
     * @notice Gets the latest update ID for a specific market and update type combination
     * @param market The market address
     * @param updateType The update type string
     * @return The latest update ID for the given market and update type, or 0 if none exists
     */
    function latestUpdateIdByMarketAndType(address market, string memory updateType) external view returns (uint256);

    /**
     * @notice Returns the total number of updates that have been published
     * @return The current update counter value
     */
    function updateCounter() external view returns (uint256);

    /**
     * @notice Fetches the most recent update for a specific parameter type in a specific market
     * @param updateType The update type identifier
     * @param market The market address
     * @return The most recent RiskParameterUpdate for the specified parameter and market
     * @custom:error NoUpdateFound Thrown if no update exists for the specified parameter and market
     */
    function getLatestUpdateByParameterAndMarket(
        string memory updateType,
        address market
    ) external view returns (RiskParameterUpdate memory);

    /**
     * @notice Fetches the update for a provided update ID
     * @param updateId The unique update ID
     * @return The RiskParameterUpdate struct for the specified update ID
     * @custom:error InvalidUpdateId Thrown if updateId is 0 or greater than updateCounter
     */
    function getUpdateById(uint256 updateId) external view returns (RiskParameterUpdate memory);

    /**
     * @notice Adds a new address to the list of authorized senders who can publish updates
     * @param sender Address to be authorized
     * @custom:error ZeroAddressNotAllowed Thrown if sender is the zero address
     * @custom:error SenderAlreadyAuthorized Thrown if sender is already authorized
     * @custom:error Unauthorized Thrown if caller is not allowed by AccessControlManager
     * @custom:event AuthorizedSenderAdded Emitted when sender is successfully added
     */
    function addAuthorizedSender(address sender) external;

    /**
     * @notice Removes an address from the list of authorized senders
     * @param sender Address to be removed from authorization
     * @custom:error SenderNotAuthorized Thrown if sender is not currently authorized
     * @custom:error Unauthorized Thrown if caller is not allowed by AccessControlManager
     * @custom:event AuthorizedSenderRemoved Emitted when sender is successfully removed
     */
    function removeAuthorizedSender(address sender) external;

    /**
     * @notice Adds a new update type to the list of authorized update types
     * @param newUpdateType New update type string to allow (must be non-empty and <= 64 characters)
     * @custom:error InvalidUpdateTypeString Thrown if update type string is empty or exceeds 64 characters
     * @custom:error UpdateTypeAlreadyExists Thrown if update type already exists
     * @custom:error Unauthorized Thrown if caller is not allowed by AccessControlManager
     * @custom:event UpdateTypeAdded Emitted when update type is successfully added
     */
    function addUpdateType(string memory newUpdateType) external;

    /**
     * @notice Sets the active status of an existing update type
     * @param updateType The update type to set active status for
     * @param active True to activate the update type, false to deactivate it
     * @custom:error UpdateTypeNotFound Thrown if update type doesn't exist
     * @custom:error UpdateTypeStatusUnchanged Thrown if status is already set to the desired value
     * @custom:error Unauthorized Thrown if caller is not allowed by AccessControlManager
     * @custom:event UpdateTypeActiveStatusChanged Emitted when status is successfully changed
     */
    function setUpdateTypeActive(string memory updateType, bool active) external;

    /**
     * @notice Publishes a new risk parameter update.
     * @param referenceId An external reference ID associated with the update
     * @param newValue The new value of the risk parameter being updated (encoded as bytes)
     * @param updateType Type of update performed, must be an active update type
     * @param market Address of the market for which the parameter update applies
     * @param poolId Pool identifier for eMode-style collateral configuration (0 for regular markets)
     * @param dstEid Destination endpoint ID for cross-chain routing
     * @param additionalData Additional data or metadata for the update
     * @custom:error SenderNotAuthorized Thrown if caller is not an authorized sender
     * @custom:error UpdateTypeNotActive Thrown if update type is not active
     * @custom:error ZeroAddressNotAllowed Thrown if market is the zero address
     * @custom:event UpdatePublished Emitted when the update is successfully published
     */
    function publishRiskParameterUpdate(
        string memory referenceId,
        bytes memory newValue,
        string memory updateType,
        address market,
        uint96 poolId,
        uint32 dstEid,
        bytes memory additionalData
    ) external;

    /**
     * @notice Publishes multiple risk parameter updates in a single transaction.
     * @param referenceIds Array of external reference IDs, one for each update
     * @param newValues Array of new values for each update (encoded as bytes)
     * @param updateTypes Array of update types, all must be active update types
     * @param markets Array of market addresses for each update
     * @param poolIds Array of pool identifiers for eMode-style collateral configuration (0 for regular markets)
     * @param dstEid Array of destination endpoint IDs for cross-chain routing
     * @param additionalData Array of additional data for each update
     * @custom:error SenderNotAuthorized Thrown if caller is not an authorized sender
     * @custom:error ArrayLengthMismatch Thrown if all arrays don't have the same length
     * @custom:error UpdateTypeNotActive Thrown if any update type is not active
     * @custom:error ZeroAddressNotAllowed Thrown if any market is the zero address
     * @custom:event UpdatePublished Emitted for each successfully published update
     */
    function publishBulkRiskParameterUpdates(
        string[] memory referenceIds,
        bytes[] memory newValues,
        string[] memory updateTypes,
        address[] memory markets,
        uint96[] memory poolIds,
        uint32[] memory dstEid,
        bytes[] memory additionalData
    ) external;
}

contracts/RiskSteward/Interfaces/IRiskSt.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { RiskParameterUpdate } from "./IRiskOracle.sol";
import { IRiskStewardReceiver } from "./IRiskStewardReceiver.sol";

/**
 * @title IRiskSteward
 * @author Venus
 * @notice Interface for risk stewards that validate and apply risk parameter updates
 */
interface IRiskSteward {
    /**
     * @notice Returns the `IRiskStewardReceiver` associated with this steward.
     * @return The risk steward receiver contract
     */
    function RISK_STEWARD_RECEIVER() external view returns (IRiskStewardReceiver);

    /**
     * @notice Checks whether an update is safe for direct execution (no timelock required).
     * @param update The risk parameter update to evaluate
     * @return True if update is safe for direct execution, false if timelock is required
     */
    function isSafeForDirectExecution(RiskParameterUpdate calldata update) external view returns (bool);

    /**
     * @notice Applies a validated risk parameter update.
     * @param update The risk parameter update to apply
     */
    function applyUpdate(RiskParameterUpdate calldata update) external;
}

// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

interface IRiskStewardReceiver {
    /**
     * @notice Status of an update
     */
    enum UpdateStatus {
        None,
        Pending,
        Executed,
        Rejected,
        Expired,
        SENT_TO_DESTINATION
    }

    /**
     * @notice Configuration for a risk parameter update type
     * @param active Whether this update type configuration is currently active
     * @param debounce Minimum delay between consecutive update executions for the same (updateType, market) pair
     * @param timelock Period that must pass after registration before an update can be executed
     * @param riskSteward Address of the risk steward contract responsible for processing this update type
     */
    struct RiskParamConfig {
        bool active;
        uint256 debounce;
        uint256 timelock;
        address riskSteward;
    }

    /**
     * @notice Registered update structure with timelock and execution information
     * @param updateId Update ID from the Risk Oracle
     * @param unlockTime Timestamp when this update can be executed (calculated as registration time + timelock)
     * @param status Current status of the update (Pending, Executed, Rejected, Expired, etc.)
     * @param executor Address of the executor who executed this update (address(0) if not executed yet)
     * @param executedAt Timestamp when this update was executed (0 if not executed yet)
     */
    struct RegisteredUpdate {
        uint256 updateId;
        uint256 unlockTime;
        UpdateStatus status;
        address executor;
        uint256 executedAt;
    }

    /**
     * @notice Event emitted when a risk parameter config is set
     */
    event RiskParameterConfigUpdated(
        bytes32 indexed updateTypeHash,
        string updateType,
        address indexed previousRiskSteward,
        address indexed riskSteward,
        uint256 previousDebounce,
        uint256 debounce,
        uint256 previousTimelock,
        uint256 timelock,
        bool previousActive,
        bool active
    );

    /**
     * @notice Event emitted when a risk parameter config active status is set
     */
    event ConfigActiveUpdated(
        bytes32 indexed updateTypeHash,
        string updateType,
        bool previousActive,
        bool indexed active
    );

    /**
     * @notice Event emitted when an update is successfully executed
     */
    event UpdateExecuted(uint256 indexed updateId);

    /**
     * @notice Event emitted when an update is rejected
     */
    event UpdateRejected(uint256 indexed updateId);

    /**
     * @notice Event emitted when an update is marked as expired
     */
    event UpdateExpired(uint256 indexed updateId);

    /**
     * @notice Event emitted when an executor status is set
     */
    event ExecutorStatusUpdated(address indexed executor, bool previousApproved, bool indexed approved);

    /**
     * @notice Event emitted when an update is registered
     */
    event UpdateRegistered(uint256 indexed updateId, uint256 unlockTime, string updateType, address indexed market);

    /**
     * @notice Event emitted when an update is sent to a destination chain
     */
    event UpdateSentToDestination(
        uint256 indexed updateId,
        uint32 indexed destLzEid,
        string updateType,
        address indexed market
    );

    /**
     * @notice Event emitted when an update is resent to a destination chain
     */
    event UpdateResentToDestination(
        uint256 indexed updateId,
        uint32 indexed destLzEid,
        string updateType,
        address indexed market
    );

    /**
     * @notice Emitted when leftover native tokens are swept by owner
     */
    event SweepNative(address indexed receiver, uint256 amount);

    /**
     * @notice Event emitted when the pause status changes
     * @param previousPaused Previous pause state
     * @param paused Current pause state
     */
    event PauseStatusUpdated(bool previousPaused, bool paused);

    /**
     * @custom:error TransferFailed
     */
    error TransferFailed();

    /**
     * @notice Thrown if a submitted update is not active and therefore cannot be processed
     */
    error ConfigNotActive();

    /**
     * @notice Thrown when an update was not applied within the required time frame
     */
    error UpdateIsExpired();

    /**
     * @notice Thrown when an update has already been processed
     */
    error UpdateAlreadyResolved();

    /**
     * @notice Thrown when the debounce period hasn't passed for applying an update to a specific market / update type
     */
    error UpdateTooFrequent();

    /**
     * @notice Thrown when an update type that is not supported is operated on
     */
    error UnsupportedUpdateType();

    /**
     * @notice Thrown when a debounce value of 0 is set
     */
    error InvalidDebounce();

    /**
     * @notice Thrown when a timelock value is greater than or equal to the expiration time
     */
    error InvalidTimelock();

    /**
     * @notice Thrown when update unlock time has not been reached
     */
    error UpdateNotUnlocked();

    /**
     * @notice Thrown when trying to resolve an update that doesn't exist
     */
    error UpdateNotFound();

    /**
     * @notice Thrown when an address is not an executor
     */
    error NotAnExecutor();

    /**
     * @notice Thrown when there is a non-expired pending update of the same type for the market
     */
    error RegisteredUpdateTypeExist(uint256);

    /**
     * @notice Thrown when trying to resend an update that is not in SENT_TO_DESTINATION status
     */
    error InvalidUpdateToResend();

    /**
     * @notice Thrown when trying to execute an update that was never registered
     */
    error InvalidRegisteredUpdate();

    /**
     * @notice Thrown when attempting to call lzSend from an address other than this contract
     */
    error InvalidLzSendCaller();

    /**
     * @notice Thrown when trying to renounce ownership
     */
    error RenounceOwnershipNotAllowed();

    /**
     * @notice Thrown when processUpdate is called while the contract is paused
     */
    error PausedError();

    /**
     * @notice Thrown when trying to set the same pause status
     */
    error PauseStatusUnchanged();

    function getRiskParameterConfig(string calldata updateType) external view returns (RiskParamConfig memory);

    function getLastProcessedUpdate(string calldata updateType, address market) external view returns (uint256);

    function getLastRegisteredUpdate(string calldata updateType, address market) external view returns (uint256);

    function setRiskParameterConfig(
        string calldata updateType,
        address riskSteward,
        uint256 debounce,
        uint256 timelock
    ) external;

    function setConfigActive(string calldata updateType, bool active) external;

    function setWhitelistedExecutor(address executor, bool approved) external;

    function processUpdate(uint256 updateId) external;

    function executeRegisteredUpdate(uint256 updateId) external;

    function rejectUpdate(uint256 updateId) external;

    function resendRemoteUpdate(uint256 updateId, bytes calldata options) external payable;

    function getExecutableUpdates(
        string calldata updateType,
        address comptroller
    ) external view returns (uint256[] memory executableUpdates);

    function isUpdateExecutable(uint256 updateId) external view returns (bool);
}

contracts/RiskSteward/IRMRiskSteward.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { RiskParameterUpdate } from "./Interfaces/IRiskOracle.sol";
import { ICorePoolVToken } from "../interfaces/ICorePoolVToken.sol";
import { IIsolatedPoolVToken } from "../interfaces/IIsolatedPoolVToken.sol";
import { InterestRateModel } from "@venusprotocol/isolated-pools/contracts/InterestRateModel.sol";
import { InterestRateModelV8 } from "@venusprotocol/venus-protocol/contracts/InterestRateModels/InterestRateModelV8.sol";
import { ICorePoolComptroller } from "../interfaces/ICorePoolComptroller.sol";
import { IRiskStewardReceiver } from "./Interfaces/IRiskStewardReceiver.sol";
import { AccessControlledV8 } from "../Governance/AccessControlledV8.sol";
import { IRiskSteward } from "./Interfaces/IRiskSteward.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";

/**
 * @title IRMRiskSteward
 * @author Venus
 * @notice Contract that can update interest rate models updates received from RiskStewardReceiver.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */
contract IRMRiskSteward is IRiskSteward, AccessControlledV8 {
    /**
     * @notice The update type for interest rate model
     */
    string public constant INTEREST_RATE_MODEL = "interestRateModel";

    /**
     * @notice The update type key for interest rate model (keccak256 hash of INTEREST_RATE_MODEL)
     */
    bytes32 public constant INTEREST_RATE_MODEL_KEY = keccak256(bytes(INTEREST_RATE_MODEL));

    /**
     * @notice Address of the BNB Core Pool Comptroller.
     * @dev This comptroller is specific to the BNB Core Pool, which uses a different ABI
     *      than isolated pools. It is used solely to detect and handle BNB Core Pool
     *      markets, and would not be used for remote-chain (isolated pool) deployments.
     */
    ICorePoolComptroller public immutable CORE_POOL_COMPTROLLER;

    /**
     * @notice Address of the RiskStewardReceiver used to validate incoming updates
     */
    IRiskStewardReceiver public immutable RISK_STEWARD_RECEIVER;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[49] private __gap;

    /**
     * @notice Emitted when an interest rate model is updated
     */
    event InterestRateModelUpdated(
        uint256 indexed updateId,
        address indexed market,
        address indexed newInterestRateModel
    );

    /**
     * @notice Thrown when an update type that is not supported is operated on
     */
    error UnsupportedUpdateType();

    /**
     * @notice Thrown when the update is not coming from the RiskStewardReceiver
     */
    error OnlyRiskStewardReceiver();

    /**
     * @notice Thrown when trying to renounce ownership
     */
    error RenounceOwnershipNotAllowed();

    /**
     * @notice Thrown when the address length is invalid
     */
    error InvalidAddressLength();

    /**
     * @notice Thrown when Core Pool VToken._setInterestRateModel fails.
     */
    error SetInterestRateModelFailed(uint256 errorCode);

    /**
     * @notice Sets the immutable CORE_POOL_COMPTROLLER and RISK_STEWARD_RECEIVER addresses and disables initializers
     * @param corePoolComptroller_ The address of the Core Pool Comptroller
     * @param riskStewardReceiver_ The address of the RiskStewardReceiver
     * @custom:error Throws ZeroAddressNotAllowed if any of the addresses are zero
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(address corePoolComptroller_, address riskStewardReceiver_) {
        ensureNonzeroAddress(riskStewardReceiver_);
        CORE_POOL_COMPTROLLER = ICorePoolComptroller(corePoolComptroller_);
        RISK_STEWARD_RECEIVER = IRiskStewardReceiver(riskStewardReceiver_);
        _disableInitializers();
    }

    /**
     * @notice Initializes the contract as ownable and access controlled.
     * @param accessControlManager_ The address of the access control manager
     */
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
    }

    /**
     * @notice Applies an interest rate model update from the RiskStewardReceiver.
     * Directly updates the market interest rate model on the vToken.
     * Delta validation is already performed by RiskStewardReceiver before execution.
     * @param update RiskParameterUpdate update to apply
     * @custom:error Throws OnlyRiskStewardReceiver if the sender is not the RiskStewardReceiver
     * @custom:error Throws UnsupportedUpdateType if the update type is not supported
     * @custom:event Emits InterestRateModelUpdated with the updateId, market and new IRM address
     * @custom:access Only callable by the RiskStewardReceiver
     */
    function applyUpdate(RiskParameterUpdate calldata update) external {
        if (msg.sender != address(RISK_STEWARD_RECEIVER)) {
            revert OnlyRiskStewardReceiver();
        }

        if (update.updateTypeKey == INTEREST_RATE_MODEL_KEY) {
            address newIRM = _decodeAbiEncodedAddress(update.newValue);
            _updateIRM(update.updateId, update.market, newIRM);
        } else {
            revert UnsupportedUpdateType();
        }
    }

    /**
     * @notice Checks if an update is safe for direct execution (no timelock required)
     * @param update The update to check
     * @return True if update is safe for direct execution, false if timelock is required
     * @custom:error Throws UnsupportedUpdateType if the update type is not supported
     * @dev For IRM updates, always returns false as we cannot compare IRM values
     */
    function isSafeForDirectExecution(RiskParameterUpdate calldata update) external pure returns (bool) {
        if (update.updateTypeKey != INTEREST_RATE_MODEL_KEY) {
            revert UnsupportedUpdateType();
        }

        // always require timelock (not safe for direct execution)
        return false;
    }

    /**
     * @notice Updates the interest rate model for the given market.
     * @param updateId The update ID from the Risk Oracle
     * @param market The market to update the interest rate model for
     * @param newIRM The new interest rate model address
     * @custom:event Emits InterestRateModelUpdated with the updateId, market and new IRM address
     */
    function _updateIRM(uint256 updateId, address market, address newIRM) internal {
        address comptroller = ICorePoolVToken(market).comptroller();

        if (comptroller == address(CORE_POOL_COMPTROLLER)) {
            uint256 errorCode = ICorePoolVToken(market)._setInterestRateModel(InterestRateModelV8(newIRM));
            if (errorCode != 0) revert SetInterestRateModelFailed(errorCode);
        } else {
            IIsolatedPoolVToken(market).setInterestRateModel(InterestRateModel(newIRM));
        }

        emit InterestRateModelUpdated(updateId, market, newIRM);
    }

    /**
     * @notice Decodes ABI-encoded bytes into an address.
     * @dev Expects exactly 32 bytes as produced by abi.encode(address).
     * @param data ABI-encoded address payload (32 bytes)
     * @return The decoded address
     * @custom:error Throws InvalidAddressLength if data length is not 32 bytes
     */
    function _decodeAbiEncodedAddress(bytes memory data) internal pure returns (address) {
        if (data.length != 32) revert InvalidAddressLength();
        return abi.decode(data, (address));
    }

    /**
     * @notice Disables renounceOwnership function
     * @custom:error Throws RenounceOwnershipNotAllowed
     */
    function renounceOwnership() public pure override {
        revert RenounceOwnershipNotAllowed();
    }
}

