// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { RiskParameterUpdate } from "./Interfaces/IRiskOracle.sol";
import { ICorePoolVToken } from "../interfaces/ICorePoolVToken.sol";
import { ICorePoolComptroller } from "../interfaces/ICorePoolComptroller.sol";
import { IRiskStewardReceiver } from "./Interfaces/IRiskStewardReceiver.sol";
import { AccessControlledV8 } from "../Governance/AccessControlledV8.sol";
import { IRiskSteward } from "./Interfaces/IRiskSteward.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";

/**
 * @title MarketCapsRiskSteward
 * @author Venus
 * @notice Contract that can update supply and borrow caps updates received from RiskStewardReceiver.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */
contract MarketCapsRiskSteward is IRiskSteward, AccessControlledV8 {
    /// @dev Max basis points i.e., 100%
    uint256 private constant MAX_BPS = 10000;

    /**
     * @notice The update type for supply caps
     */
    string public constant SUPPLY_CAP = "supplyCap";

    /**
     * @notice The update type key for supply caps (keccak256 hash of SUPPLY_CAP)
     */
    bytes32 public constant SUPPLY_CAP_KEY = keccak256(bytes(SUPPLY_CAP));

    /**
     * @notice The update type for borrow caps
     */
    string public constant BORROW_CAP = "borrowCap";

    /**
     * @notice The update type key for borrow caps (keccak256 hash of BORROW_CAP)
     */
    bytes32 public constant BORROW_CAP_KEY = keccak256(bytes(BORROW_CAP));

    /**
     * @notice Address of the RiskStewardReceiver used to validate incoming updates
     */
    IRiskStewardReceiver public immutable RISK_STEWARD_RECEIVER;

    /**
     * @notice The safe delta threshold in basis points.
     * @notice Updates within this delta are considered safe and require no timelock. Updates exceeding this delta require timelock.
     */
    uint256 public safeDeltaBps;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[49] private __gap;

    /**
     * @notice Emitted when a supply cap is updated
     */
    event SupplyCapUpdated(uint256 indexed updateId, address indexed market, uint256 newSupplyCap);

    /**
     * @notice Emitted when a borrow cap is updated
     */
    event BorrowCapUpdated(uint256 indexed updateId, address indexed market, uint256 newBorrowCap);

    /**
     * @notice Emitted when the safe delta bps is updated
     */
    event SafeDeltaBpsUpdated(uint256 indexed oldSafeDeltaBps, uint256 indexed newSafeDeltaBps);

    /**
     * @notice Thrown when a safeDeltaBps value is greater than MAX_BPS
     */
    error InvalidSafeDeltaBps();

    /**
     * @notice Thrown when an update type that is not supported is operated on
     */
    error UnsupportedUpdateType();

    /**
     * @notice Thrown when the update is not coming from the RiskStewardReceiver
     */
    error OnlyRiskStewardReceiver();

    /**
     * @notice Thrown when trying to renounce ownership
     */
    error RenounceOwnershipNotAllowed();

    /**
     * @notice Thrown when the uint256 data length is invalid
     */
    error InvalidUintLength();

    /**
     * @notice Sets the immutable RiskStewardReceiver address and disables initializers
     * @param riskStewardReceiver_ The address of the RiskStewardReceiver
     * @custom:error Throws ZeroAddressNotAllowed if the RiskStewardReceiver address is zero
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(address riskStewardReceiver_) {
        ensureNonzeroAddress(riskStewardReceiver_);
        RISK_STEWARD_RECEIVER = IRiskStewardReceiver(riskStewardReceiver_);
        _disableInitializers();
    }

    /**
     * @notice Initializes the contract as ownable and access controlled.
     * @param accessControlManager_ The address of the access control manager
     */
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
    }

    /**
     * @notice Sets the safe delta bps
     * @param safeDeltaBps_ The new safe delta bps
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits SafeDeltaBpsUpdated with the old and new safe delta bps
     * @custom:error Throws InvalidSafeDeltaBps if the safe delta bps is greater than MAX_BPS
     */
    function setSafeDeltaBps(uint256 safeDeltaBps_) external {
        _checkAccessAllowed("setSafeDeltaBps(uint256)");
        if (safeDeltaBps_ > MAX_BPS) {
            revert InvalidSafeDeltaBps();
        }
        emit SafeDeltaBpsUpdated(safeDeltaBps, safeDeltaBps_);
        safeDeltaBps = safeDeltaBps_;
    }

    /**
     * @notice Checks if an update is safe for direct execution (no timelock required)
     * @param update The update to check
     * @return True if update is safe for direct execution, false if timelock is required
     * @custom:error Throws UnsupportedUpdateType if the update type is not supported
     */
    function isSafeForDirectExecution(RiskParameterUpdate calldata update) external view returns (bool) {
        uint256 newValue = _decodeAbiEncodedUint256(update.newValue);
        ICorePoolComptroller comptroller = ICorePoolComptroller(ICorePoolVToken(update.market).comptroller());
        uint256 currentValue;

        if (update.updateTypeKey == SUPPLY_CAP_KEY) {
            currentValue = comptroller.supplyCaps(update.market);
        } else if (update.updateTypeKey == BORROW_CAP_KEY) {
            currentValue = comptroller.borrowCaps(update.market);
        } else {
            revert UnsupportedUpdateType();
        }

        // If current value is 0, always require timelock (not safe for direct execution)
        if (currentValue == 0) {
            return false;
        }

        // Return true if difference is within safe delta (safe for direct execution)
        return _isWithinSafeDelta(newValue, currentValue);
    }

    /**
     * @notice Applies a market cap update from the RiskStewardReceiver.
     * Directly updates the market supply or borrow cap on the market's comptroller.
     * @custom:access Only callable by the RiskStewardReceiver
     * @param update RiskParameterUpdate update to apply
     * @custom:event Emits SupplyCapUpdated or BorrowCapUpdated depending on the update with the updateId, market and new cap
     * @custom:error Throws OnlyRiskStewardReceiver if the sender is not the RiskStewardReceiver
     * @custom:error Throws UnsupportedUpdateType if the update type is not supported
     */
    function applyUpdate(RiskParameterUpdate calldata update) external {
        if (msg.sender != address(RISK_STEWARD_RECEIVER)) {
            revert OnlyRiskStewardReceiver();
        }
        uint256 newValue = _decodeAbiEncodedUint256(update.newValue);

        if (update.updateTypeKey == SUPPLY_CAP_KEY) {
            _updateSupplyCaps(update.updateId, update.market, newValue);
        } else if (update.updateTypeKey == BORROW_CAP_KEY) {
            _updateBorrowCaps(update.updateId, update.market, newValue);
        } else {
            revert UnsupportedUpdateType();
        }
    }

    /**
     * @notice Updates the supply cap for the given market.
     * @param updateId The update ID from the Risk Oracle
     * @param market The market to update the supply cap for
     * @param newValue The new supply cap value
     * @custom:event Emits SupplyCapUpdated with the updateId, market and new supply cap
     */
    function _updateSupplyCaps(uint256 updateId, address market, uint256 newValue) internal {
        address comptroller = ICorePoolVToken(market).comptroller();
        address[] memory newSupplyCapMarkets = new address[](1);
        newSupplyCapMarkets[0] = market;
        uint256[] memory newSupplyCaps = new uint256[](1);
        newSupplyCaps[0] = newValue;

        // Core and isolated pools share the same `setMarketSupplyCaps` signature.
        ICorePoolComptroller(comptroller).setMarketSupplyCaps(newSupplyCapMarkets, newSupplyCaps);
        emit SupplyCapUpdated(updateId, market, newSupplyCaps[0]);
    }

    /**
     * @notice Updates the borrow cap for the given market.
     * @param updateId The update ID from the Risk Oracle
     * @param market The market to update the borrow cap for
     * @param newValue The new borrow cap value
     * @custom:event Emits BorrowCapUpdated with the updateId, market and new borrow cap
     */
    function _updateBorrowCaps(uint256 updateId, address market, uint256 newValue) internal {
        address comptroller = ICorePoolVToken(market).comptroller();
        address[] memory newBorrowCapMarkets = new address[](1);
        newBorrowCapMarkets[0] = market;
        uint256[] memory newBorrowCaps = new uint256[](1);
        newBorrowCaps[0] = newValue;

        //Core and isolated pools share the same `setMarketBorrowCaps` signature,
        ICorePoolComptroller(comptroller).setMarketBorrowCaps(newBorrowCapMarkets, newBorrowCaps);
        emit BorrowCapUpdated(updateId, market, newBorrowCaps[0]);
    }

    /**
     * @notice Checks if the difference between new and current values is within the safe delta threshold.
     * @param newValue The new value to check
     * @param currentValue The current value to compare against
     * @return True if the difference is within the safe delta, false otherwise
     */
    function _isWithinSafeDelta(uint256 newValue, uint256 currentValue) internal view returns (bool) {
        uint256 diff = newValue > currentValue ? newValue - currentValue : currentValue - newValue;
        uint256 maxDiff = (safeDeltaBps * currentValue) / MAX_BPS;
        return diff <= maxDiff;
    }

    /**
     * @notice Decodes ABI-encoded bytes into a uint256.
     * @dev Expects exactly 32 bytes as produced by abi.encode(uint256).
     * @param data ABI-encoded uint256 payload (32 bytes)
     * @return value Decoded uint256
     */
    function _decodeAbiEncodedUint256(bytes memory data) internal pure returns (uint256 value) {
        if (data.length != 32) {
            revert InvalidUintLength();
        }

        value = abi.decode(data, (uint256));
    }

    /**
     * @notice Disables renounceOwnership function
     * @custom:error Throws RenounceOwnershipNotAllowed
     */
    function renounceOwnership() public pure override {
        revert RenounceOwnershipNotAllowed();
    }
}

contracts/RiskSteward/RiskOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

import { AccessControlledV8 } from "../Governance/AccessControlledV8.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";
import { IRiskOracle, RiskParameterUpdate } from "./Interfaces/IRiskOracle.sol";

/**
 * @title Risk Oracle
 * @author Venus
 * @notice Contract for managing and publishing risk parameter updates for Risk-Steward Updates
 */
contract RiskOracle is IRiskOracle, AccessControlledV8 {
    /// @notice Array to store all update types
    string[] public allUpdateTypes;

    /// @notice Whitelist of valid update type identifiers
    mapping(string => bool) public activeUpdateTypes;

    /// @notice Mapping from unique update ID to the update details
    mapping(uint256 => RiskParameterUpdate) public updatesById;

    /// @notice Authorized accounts capable of proposing updates
    mapping(address => bool) public authorizedSenders;

    /// @notice Mapping to store the latest update ID for each combination of market and update type
    mapping(address => mapping(string => uint256)) public latestUpdateIdByMarketAndType;

    /// @notice Counter to keep track of the total number of updates
    uint256 public updateCounter;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[44] private __gap;

    /// @notice Event emitted when a risk parameter update is published
    event UpdatePublished(
        string referenceId,
        uint256 indexed updateId,
        address indexed market,
        string indexed updateType,
        bytes newValue,
        bytes previousValue,
        uint256 timestamp,
        address publisher,
        bytes additionalData
    );

    /// @notice Event emitted when a new authorized sender is added
    event AuthorizedSenderAdded(address indexed sender);

    /// @notice Event emitted when an authorized sender is removed
    event AuthorizedSenderRemoved(address indexed sender);

    /// @notice Event emitted when a new update type is added
    event UpdateTypeAdded(string indexed updateType);

    /// @notice Event emitted when an update type's active status is changed
    event UpdateTypeActiveStatusChanged(string indexed updateType, bool previousActive, bool indexed active);

    /// @notice Thrown when sender is not authorized
    error SenderNotAuthorized();

    /// @notice Thrown when sender is already authorized
    error SenderAlreadyAuthorized();

    /// @notice Thrown when update type string is invalid
    error InvalidUpdateTypeString();

    /// @notice Thrown when update type already exists
    error UpdateTypeAlreadyExists();

    /// @notice Thrown when update type doesn't exist
    error UpdateTypeNotFound();

    /// @notice Thrown when update type active status is already set to the desired value
    error UpdateTypeStatusUnchanged();

    /// @notice Thrown when update type is not active
    error UpdateTypeNotActive();

    /// @notice Thrown when no update is found
    error NoUpdateFound();

    /// @notice Thrown when update ID is invalid
    error InvalidUpdateId();

    /// @notice Thrown when array lengths don't match in bulk operations
    error ArrayLengthMismatch();

    /**
     * @notice Modifier that restricts function access to authorized senders only
     */
    modifier onlyAuthorized() {
        if (!authorizedSenders[msg.sender]) {
            revert SenderNotAuthorized();
        }
        _;
    }

    /**
     * @notice Disables initializers
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initializes the contract with access control manager
     * @param accessControlManager_ Address of the access control manager
     * @custom:error Throws ZeroAddressNotAllowed if accessControlManager_ is zero address
     */
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
    }

    /**
     * @notice Adds a new sender to the list of addresses authorized to perform updates
     * @param sender Address to be authorized
     * @custom:error Throws ZeroAddressNotAllowed if sender is zero address
     * @custom:error Throws SenderAlreadyAuthorized if sender is already authorized
     * @custom:error Throws Unauthorized if caller is not allowed by AccessControlManager
     * @custom:event Emits AuthorizedSenderAdded when sender is successfully added
     */
    function addAuthorizedSender(address sender) external {
        _checkAccessAllowed("addAuthorizedSender(address)");
        ensureNonzeroAddress(sender);
        if (authorizedSenders[sender]) {
            revert SenderAlreadyAuthorized();
        }
        authorizedSenders[sender] = true;
        emit AuthorizedSenderAdded(sender);
    }

    /**
     * @notice Removes an address from the list of authorized senders
     * @param sender Address to be unauthorized
     * @custom:error Throws SenderNotAuthorized if sender is not currently authorized
     * @custom:error Throws Unauthorized if caller is not allowed by AccessControlManager
     * @custom:event Emits AuthorizedSenderRemoved when sender is successfully removed
     */
    function removeAuthorizedSender(address sender) external {
        _checkAccessAllowed("removeAuthorizedSender(address)");
        if (!authorizedSenders[sender]) {
            revert SenderNotAuthorized();
        }
        authorizedSenders[sender] = false;
        emit AuthorizedSenderRemoved(sender);
    }

    /**
     * @notice Adds a new type of update to the list of authorized update types
     * @param newUpdateType New type of update to allow
     * @custom:error Throws InvalidUpdateTypeString if update type string is empty or exceeds 64 characters
     * @custom:error Throws UpdateTypeAlreadyExists if update type already exists
     * @custom:error Throws Unauthorized if caller is not allowed by AccessControlManager
     * @custom:event Emits UpdateTypeAdded when update type is successfully added
     */
    function addUpdateType(string memory newUpdateType) external {
        _checkAccessAllowed("addUpdateType(string)");
        if (bytes(newUpdateType).length == 0 || bytes(newUpdateType).length > 64) {
            revert InvalidUpdateTypeString();
        }
        if (_updateTypeExists(newUpdateType)) {
            revert UpdateTypeAlreadyExists();
        }
        activeUpdateTypes[newUpdateType] = true;
        allUpdateTypes.push(newUpdateType);
        emit UpdateTypeAdded(newUpdateType);
    }

    /**
     * @notice Sets the active status of an existing update type
     * @param updateType The update type to set active status for
     * @param active True to activate, false to deactivate
     * @custom:error Throws UpdateTypeNotFound if update type doesn't exist
     * @custom:error Throws UpdateTypeStatusUnchanged if status is already set to the desired value
     * @custom:error Throws Unauthorized if caller is not allowed by AccessControlManager
     * @custom:event Emits UpdateTypeActiveStatusChanged when status is successfully changed
     */
    function setUpdateTypeActive(string memory updateType, bool active) external {
        _checkAccessAllowed("setUpdateTypeActive(string,bool)");

        if (!_updateTypeExists(updateType)) {
            revert UpdateTypeNotFound();
        }

        bool previousActive = activeUpdateTypes[updateType];
        if (previousActive == active) {
            revert UpdateTypeStatusUnchanged();
        }

        activeUpdateTypes[updateType] = active;
        emit UpdateTypeActiveStatusChanged(updateType, previousActive, active);
    }

    /**
     * @notice Publishes a new risk parameter update
     * @param referenceId An external reference ID associated with the update
     * @param newValue The new value of the risk parameter being updated
     * @param updateType Type of update performed, must be previously authorized
     * @param market Address for market of the parameter update
     * @param poolId Pool identifier for eMode-style collateral configuration (0 for regular markets)
     * @param dstEid Destination endpoint ID for cross-chain routing
     * @param additionalData Additional data for the update
     * @custom:error Throws SenderNotAuthorized if caller is not an authorized sender
     * @custom:error Throws UpdateTypeNotActive if update type is not active
     * @custom:event Emits UpdatePublished when update is successfully published
     */
    function publishRiskParameterUpdate(
        string memory referenceId,
        bytes memory newValue,
        string memory updateType,
        address market,
        uint96 poolId,
        uint32 dstEid,
        bytes memory additionalData
    ) external onlyAuthorized {
        _publishUpdate(referenceId, newValue, updateType, market, poolId, dstEid, additionalData);
    }

    /**
     * @notice Publishes multiple risk parameter updates in a single transaction
     * @param referenceIds Array of external reference IDs
     * @param newValues Array of new values for each update
     * @param updateTypes Array of types for each update, all must be authorized
     * @param markets Array of addresses for markets of the parameter updates
     * @param poolIds Array of pool identifiers for eMode-style collateral configuration (0 for regular markets)
     * @param dstEid Array of destination endpoint IDs for cross-chain routing
     * @param additionalData Array of additional data for the updates
     * @custom:error Throws SenderNotAuthorized if caller is not an authorized sender
     * @custom:error Throws UpdateTypeNotActive if any update type is not active
     * @custom:event Emits UpdatePublished for each successfully published update
     */
    function publishBulkRiskParameterUpdates(
        string[] memory referenceIds,
        bytes[] memory newValues,
        string[] memory updateTypes,
        address[] memory markets,
        uint96[] memory poolIds,
        uint32[] memory dstEid,
        bytes[] memory additionalData
    ) external onlyAuthorized {
        uint256 length = referenceIds.length;
        if (
            length == 0 ||
            length != newValues.length ||
            length != updateTypes.length ||
            length != markets.length ||
            length != poolIds.length ||
            length != dstEid.length ||
            length != additionalData.length
        ) {
            revert ArrayLengthMismatch();
        }
        for (uint256 i = 0; i < length; ++i) {
            _publishUpdate(
                referenceIds[i],
                newValues[i],
                updateTypes[i],
                markets[i],
                poolIds[i],
                dstEid[i],
                additionalData[i]
            );
        }
    }

    /**
     * @notice Fetches the most recent update for a specific parameter in a specific market
     * @param updateType The identifier for the parameter
     * @param market The market identifier
     * @return The most recent RiskParameterUpdate for the specified parameter and market
     * @custom:error Throws NoUpdateFound if no update exists for the specified parameter and market
     */
    function getLatestUpdateByParameterAndMarket(
        string memory updateType,
        address market
    ) external view returns (RiskParameterUpdate memory) {
        uint256 updateId = latestUpdateIdByMarketAndType[market][updateType];
        if (updateId == 0) {
            revert NoUpdateFound();
        }
        return updatesById[updateId];
    }

    /**
     * @notice Fetches the update for a provided updateId
     * @param updateId Update ID
     * @return The RiskParameterUpdate for the specified id
     * @custom:error Throws InvalidUpdateId if updateId is 0 or greater than updateCounter
     */
    function getUpdateById(uint256 updateId) external view returns (RiskParameterUpdate memory) {
        if (updateId == 0 || updateId > updateCounter) {
            revert InvalidUpdateId();
        }
        return updatesById[updateId];
    }

    /**
     * @notice Publishes a new risk parameter update internally
     * @param referenceId An external reference ID associated with the update
     * @param newValue The new value of the risk parameter being updated
     * @param updateType Type of update performed, must be previously authorized
     * @param market Address for market of the parameter update
     * @param poolId Pool identifier for eMode-style collateral configuration (0 for regular markets)
     * @param dstEid Destination endpoint ID for cross-chain routing
     * @param additionalData Additional data for the update
     * @custom:error Throws ZeroAddressNotAllowed if market is zero address
     * @custom:error Throws UpdateTypeNotActive if update type is not active
     * @custom:event Emits UpdatePublished when update is successfully published
     */
    function _publishUpdate(
        string memory referenceId,
        bytes memory newValue,
        string memory updateType,
        address market,
        uint96 poolId,
        uint32 dstEid,
        bytes memory additionalData
    ) internal {
        ensureNonzeroAddress(market);
        if (!activeUpdateTypes[updateType]) {
            revert UpdateTypeNotActive();
        }
        ++updateCounter;
        uint256 previousUpdateId = latestUpdateIdByMarketAndType[market][updateType];
        bytes memory previousValue = updatesById[previousUpdateId].newValue;

        bytes32 updateTypeKey = keccak256(bytes(updateType));

        RiskParameterUpdate memory newUpdate = RiskParameterUpdate({
            referenceId: referenceId,
            updateId: updateCounter,
            market: market,
            updateType: updateType,
            updateTypeKey: updateTypeKey,
            newValue: newValue,
            previousValue: previousValue,
            timestamp: block.timestamp,
            publisher: msg.sender,
            poolId: poolId,
            destLzEid: dstEid,
            additionalData: additionalData
        });
        updatesById[updateCounter] = newUpdate;

        // Update the latest update ID for the market and updateType
        latestUpdateIdByMarketAndType[market][updateType] = updateCounter;

        emit UpdatePublished(
            referenceId,
            updateCounter,
            market,
            updateType,
            newValue,
            previousValue,
            block.timestamp,
            msg.sender,
            additionalData
        );
    }

    /**
     * @notice Returns the total number of update types in the allUpdateTypes array
     * @return The length of the allUpdateTypes array
     */
    function allUpdateTypesLength() external view returns (uint256) {
        return allUpdateTypes.length;
    }

    /**
     * @notice Returns all update types in the allUpdateTypes array
     * @return An array of all update type strings
     */
    function getAllUpdateTypes() external view returns (string[] memory) {
        return allUpdateTypes;
    }

    /**
     * @notice Checks if an update type exists in the allUpdateTypes array
     * @param updateType The update type to check
     * @return True if the update type exists, false otherwise
     */
    function _updateTypeExists(string memory updateType) internal view returns (bool) {
        for (uint256 i = 0; i < allUpdateTypes.length; ++i) {
            if (keccak256(bytes(allUpdateTypes[i])) == keccak256(bytes(updateType))) {
                return true;
            }
        }
        return false;
    }
}

contracts/RiskSteward/RiskStewardReceive.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { OwnableUpgradeable } from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { IRiskSteward } from "./Interfaces/IRiskSteward.sol";
import { IRiskOracle, RiskParameterUpdate } from "./Interfaces/IRiskOracle.sol";
import { IRiskStewardReceiver } from "./Interfaces/IRiskStewardReceiver.sol";
import { AccessControlledV8 } from "../Governance/AccessControlledV8.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";
import { ICorePoolComptroller } from "../interfaces/ICorePoolComptroller.sol";
import { OAppUpgradeable, MessagingFee, Origin } from "@layerzerolabs/oapp-evm-upgradeable/contracts/oapp/OAppUpgradeable.sol";
import { OptionsBuilder } from "@layerzerolabs/oapp-evm/contracts/oapp/libs/OptionsBuilder.sol";

/**
 * @title RiskStewardReceiver
 * @author Venus
 * @notice Contract that reads updates from a Risk Oracle, validates them with timelock and debounce,
 *         and either executes them locally via the configured RiskSteward or forwards them cross‑chain.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */
contract RiskStewardReceiver is IRiskStewardReceiver, AccessControlledV8, OAppUpgradeable {
    using OptionsBuilder for bytes;

    /**
     * @notice Period after which a proposed update becomes expired and can no longer be applied
     */
    uint256 public constant UPDATE_EXPIRATION_TIME = 2 days;

    /**
     * @notice Source chain LayerZero endpoint ID
     */
    uint32 public immutable LAYER_ZERO_EID;

    /**
     * @notice The Risk Oracle contract address
     */
    IRiskOracle public immutable RISK_ORACLE;

    /**
     * @notice Pause flag
     */
    bool public paused;

    /**
     * @notice Mapping of supported risk configurations and their validation parameters (keyed by hashed updateType)
     */
    mapping(bytes32 => RiskParamConfig) public riskParameterConfigs;

    /**
     * @notice Master storage of all registered updates by update ID
     */
    mapping(uint256 updateId => RegisteredUpdate) public updates;

    /**
     * @notice Track last processed update ID per (updateTypeKey, market)
     */
    mapping(bytes32 => mapping(address market => uint256)) public lastProcessedUpdate;

    /**
     * @notice Track the current registered update per (updateType, market) to avoid registering multiple updates
     */
    mapping(bytes32 => mapping(address market => uint256)) public lastRegisteredUpdate;

    /**
     * @notice Mapping from executor address to whitelist status
     */
    mapping(address => bool) public whitelistedExecutors;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[44] private __gap;

    /**
     * @dev Ensures the caller is a whitelisted executor.
     */
    modifier onlyWhitelistedExecutors() {
        if (!whitelistedExecutors[msg.sender]) {
            revert NotAnExecutor();
        }
        _;
    }

    /**
     * @dev Ensures the contract is not paused.
     */
    modifier whenNotPaused() {
        if (paused) {
            revert PausedError();
        }
        _;
    }

    /**
     * @notice Disables initializers and sets the Risk Oracle and LayerZero configuration.
     * @param riskOracle_ The address of the Risk Oracle contract.
     * @param endpoint_ The LayerZero endpoint contract used by the underlying `OAppUpgradeable`.
     * @param layerZeroLzEid_ The LayerZero endpoint ID (EID) for this chain.
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(address riskOracle_, address endpoint_, uint32 layerZeroLzEid_) OAppUpgradeable(endpoint_) {
        _disableInitializers();
        ensureNonzeroAddress(riskOracle_);
        RISK_ORACLE = IRiskOracle(riskOracle_);
        LAYER_ZERO_EID = layerZeroLzEid_;
    }

    /**
     * @notice Initializes the contract with the Access Control Manager and OApp owner.
     * @param acm_ The address of the Access Control Manager
     * @param delegate_ The address of the OApp owner passed to `__OApp_init`.
     */
    function initialize(address acm_, address delegate_) external initializer {
        __AccessControlled_init(acm_);
        __OApp_init(delegate_);
    }

    /**
     * @notice Accepts native tokens (e.g., BNB) sent to this contract.
     */
    receive() external payable {}

    /**
     * @notice Allows the owner to sweep leftover native tokens (e.g., BNB) from the contract.
     * @custom:event Emits SweepNative event.
     */
    function sweepNative() external onlyOwner {
        uint256 balance = address(this).balance;
        if (balance > 0) {
            (bool success, ) = payable(owner()).call{ value: balance }("");
            if (!success) revert TransferFailed();
            emit SweepNative(owner(), balance);
        }
    }

    /**
     * @notice Sets the pause status for `processUpdate`.
     * @param paused_ True to pause, false to unpause
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits PauseStatusUpdated
     */
    function setPaused(bool paused_) external {
        _checkAccessAllowed("setPaused(bool)");
        if (paused == paused_) {
            revert PauseStatusUnchanged();
        }
        emit PauseStatusUpdated(paused, paused_);
        paused = paused_;
    }

    /**
     * @notice Sets the risk parameter config for a given update type
     * @param updateType The type of update to configure
     * @param riskSteward The address for the risk steward contract responsible for processing the update
     * @param debounce The debounce period for the update
     * @param timelock The timelock period before the update can be executed
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits RiskParameterConfigUpdated
     * @custom:error Throws UnsupportedUpdateType if the update type is an empty string
     * @custom:error Throws InvalidDebounce if the debounce is 0
     * @custom:error Throws InvalidTimelock if the timelock is greater than or equal to the expiration time
     * @custom:error Throws ZeroAddressNotAllowed if the risk steward address is zero
     */
    function setRiskParameterConfig(
        string calldata updateType,
        address riskSteward,
        uint256 debounce,
        uint256 timelock
    ) external {
        _checkAccessAllowed("setRiskParameterConfig(string,address,uint256,uint256)");
        ensureNonzeroAddress(riskSteward);

        if (bytes(updateType).length == 0) {
            revert UnsupportedUpdateType();
        }
        if (debounce == 0) {
            revert InvalidDebounce();
        }
        if (timelock >= UPDATE_EXPIRATION_TIME) {
            revert InvalidTimelock();
        }

        bytes32 key = keccak256(bytes(updateType));
        RiskParamConfig memory previousConfig = riskParameterConfigs[key];

        riskParameterConfigs[key] = RiskParamConfig({
            active: true,
            riskSteward: riskSteward,
            debounce: debounce,
            timelock: timelock
        });

        emit RiskParameterConfigUpdated(
            key,
            updateType,
            previousConfig.riskSteward,
            riskSteward,
            previousConfig.debounce,
            debounce,
            previousConfig.timelock,
            timelock,
            previousConfig.active,
            true
        );
    }

    /**
     * @notice Sets the active status of a risk parameter config
     * @param updateType The type of update to configure
     * @param active The active status to set
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits ConfigActiveUpdated with the update type hash, update type, previous active status, and the active status
     * @custom:error Throws UnsupportedUpdateType if the update type is not supported
     */
    function setConfigActive(string calldata updateType, bool active) external {
        _checkAccessAllowed("setConfigActive(string,bool)");
        bytes32 key = keccak256(bytes(updateType));

        if (riskParameterConfigs[key].riskSteward == address(0)) {
            revert UnsupportedUpdateType();
        }

        bool previousActive = riskParameterConfigs[key].active;
        if (previousActive == active) {
            return;
        }

        riskParameterConfigs[key].active = active;
        emit ConfigActiveUpdated(key, updateType, previousActive, active);
    }

    /**
     * @notice Manages the whitelist of executors that are allowed to execute timelocked registered updates.
     * @param executor The address of the executor
     * @param approved The whitelist status to set (true to whitelist, false to remove)
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits ExecutorStatusUpdated with the executor address, previous approval status, and approval status
     * @custom:error Throws ZeroAddressNotAllowed if the executor address is zero
     */
    function setWhitelistedExecutor(address executor, bool approved) external {
        _checkAccessAllowed("setWhitelistedExecutor(address,bool)");
        ensureNonzeroAddress(executor);

        bool previousApproved = whitelistedExecutors[executor];
        if (previousApproved == approved) {
            return;
        }

        whitelistedExecutors[executor] = approved;
        emit ExecutorStatusUpdated(executor, previousApproved, approved);
    }

    /**
     * @notice Processes an update from the Risk Oracle. Validates, registers the update,
     * and either executes immediately, registers with timelock, or forwards cross-chain.
     * @param updateId The update ID from the oracle's perspective
     * @custom:event Emits UpdateRegistered, UpdateExecuted, or UpdateSentToDestination depending on the update type
     * @custom:error Throws UpdateAlreadyResolved if the update was already processed
     * @custom:error Throws UpdateIsExpired if the update has expired
     * @custom:error Throws ConfigNotActive if the config is not active
     * @custom:error Throws UpdateTooFrequent if the debounce period has not passed
     * @custom:error Throws RegisteredUpdateTypeExist if there is a non-expired pending update of the same type
     */
    function processUpdate(uint256 updateId) external whenNotPaused {
        RiskParameterUpdate memory update = RISK_ORACLE.getUpdateById(updateId);
        RiskParamConfig storage config = riskParameterConfigs[update.updateTypeKey];
        _ensureNoActiveUpdate(update);
        _validateRegisterUpdate(update, config);

        bool isRemoteUpdate = update.destLzEid != 0 && update.destLzEid != LAYER_ZERO_EID;

        IRiskSteward riskSteward = IRiskSteward(config.riskSteward);
        bool safeForDirectExecution = isRemoteUpdate ? false : riskSteward.isSafeForDirectExecution(update);

        _registerUpdate(update, config, safeForDirectExecution, isRemoteUpdate);

        if (isRemoteUpdate) {
            _sendRemoteUpdate(update, "", 0);
        } else if (safeForDirectExecution) {
            _executeUpdate(update, riskSteward);
        }
    }

    /**
     * @notice Executes a registered update. Only whitelisted executors can call this function.
     *         This function can be used for updates that have completed their timelock and are ready to execute.
     * @param updateId The oracle update ID of the update to execute
     * @custom:access Only whitelisted executors can call this function
     * @custom:event Emits UpdateExecuted with the oracle update ID
     * @custom:error Throws NotAnExecutor if the caller is not a whitelisted executor
     * @custom:error Throws InvalidRegisteredUpdate if the update was never registered
     * @custom:error Throws UpdateAlreadyResolved if the update was already executed or rejected
     * @custom:error Throws UpdateIsExpired if the update has expired
     * @custom:error Throws ConfigNotActive if the config is not active
     * @custom:error Throws UpdateNotUnlocked if the unlock time has not passed
     */
    function executeRegisteredUpdate(uint256 updateId) external onlyWhitelistedExecutors {
        RegisteredUpdate storage registeredUpdate = updates[updateId];
        RiskParameterUpdate memory update = RISK_ORACLE.getUpdateById(updateId);
        RiskParamConfig storage config = riskParameterConfigs[update.updateTypeKey];

        _validateExecuteUpdate(registeredUpdate, update, config);
        _executeUpdate(update, IRiskSteward(config.riskSteward));
    }

    /**
     * @notice Rejects a registered update
     * @param updateId The oracle update ID of the update to reject
     * @custom:access Only whitelisted executors can call this function
     * @custom:event Emits UpdateRejected with the oracle update ID
     * @custom:error Throws UpdateAlreadyResolved if the update was already executed or rejected
     */
    function rejectUpdate(uint256 updateId) external onlyWhitelistedExecutors {
        RegisteredUpdate storage registeredUpdate = updates[updateId];

        if (registeredUpdate.status != UpdateStatus.Pending) {
            revert UpdateAlreadyResolved();
        }

        registeredUpdate.status = UpdateStatus.Rejected;
        emit UpdateRejected(updateId);
    }

    /**
     * @notice Resends a remote update to the destination chain. This function is useful in case of bridge failures.
     * @dev Duplicate update rejection is handled in the destination contract itself, so resending
     *      the same update multiple times is safe and will be deduplicated on the destination side.
     * @param updateId The oracle update ID to resend
     * @param options LayerZero message options; if empty, default executor option is used
     * @custom:access Only whitelisted executors can call this function
     * @custom:event Emits UpdateResentToDestination with the update ID, destination chain ID, update type, and market
     * @custom:error Throws NotAnExecutor if the caller is not a whitelisted executor
     * @custom:error Throws InvalidUpdateToResend if the update status is not SENT_TO_DESTINATION
     * @custom:error Throws UpdateIsExpired if the update has expired
     */
    function resendRemoteUpdate(uint256 updateId, bytes calldata options) external payable onlyWhitelistedExecutors {
        RegisteredUpdate storage registeredUpdate = updates[updateId];
        if (registeredUpdate.status != UpdateStatus.SENT_TO_DESTINATION) {
            revert InvalidUpdateToResend();
        }

        RiskParameterUpdate memory update = RISK_ORACLE.getUpdateById(updateId);

        // Check if update is expired
        if (update.timestamp + UPDATE_EXPIRATION_TIME < block.timestamp) {
            revert UpdateIsExpired();
        }

        _sendRemoteUpdate(update, options, msg.value);
        emit UpdateResentToDestination(update.updateId, update.destLzEid, update.updateType, update.market);
    }

    /**
     * @notice Returns an array of update IDs for executable registered updates for a given update type and comptroller.
     * @param updateType The human‑readable identifier of the update type to filter by
     * @param comptroller The address of the Isolated Pools Comptroller that manages the markets
     * @return executableUpdates Array of update IDs that are ready to be executed
     */
    function getExecutableUpdates(
        string calldata updateType,
        address comptroller
    ) external view returns (uint256[] memory executableUpdates) {
        bytes32 updateTypeKey = keccak256(bytes(updateType));
        address[] memory markets = ICorePoolComptroller(comptroller).getAllMarkets();
        uint256 maxUpdates = markets.length;
        uint256[] memory tempArray = new uint256[](maxUpdates);
        uint256 count = 0;

        for (uint256 i = 0; i < maxUpdates; ++i) {
            uint256 registeredUpdateId = lastRegisteredUpdate[updateTypeKey][markets[i]];
            if (!_isUpdateExecutable(registeredUpdateId)) continue;
            tempArray[count] = registeredUpdateId;
            count++;
        }

        // shrink array to real size
        executableUpdates = new uint256[](count);
        for (uint256 i = 0; i < count; ++i) {
            executableUpdates[i] = tempArray[i];
        }
    }

    /**
     * @notice Returns whether a registered update is ready to be executed.
     * @param updateId The oracle update ID to query
     * @return True if the update is pending, not expired, active, and past its timelock
     */
    function isUpdateExecutable(uint256 updateId) external view returns (bool) {
        return _isUpdateExecutable(updateId);
    }

    /**
     * @notice Returns the risk parameter configuration for a given update type
     * @param updateType The human-readable identifier of the update type
     * @return The risk parameter configuration
     */
    function getRiskParameterConfig(string calldata updateType) external view returns (RiskParamConfig memory) {
        bytes32 key = keccak256(bytes(updateType));
        return riskParameterConfigs[key];
    }

    /**
     * @notice Returns the last processed update ID for a given update type and market
     * @param updateType The human-readable identifier of the update type
     * @param market The address of the market
     * @return The last processed update ID
     */
    function getLastProcessedUpdate(string calldata updateType, address market) external view returns (uint256) {
        bytes32 key = keccak256(bytes(updateType));
        return lastProcessedUpdate[key][market];
    }

    /**
     * @notice Returns the last registered update ID for a given update type and market
     * @param updateType The human-readable identifier of the update type
     * @param market The address of the market
     * @return The last registered update ID
     */
    function getLastRegisteredUpdate(string calldata updateType, address market) external view returns (uint256) {
        bytes32 key = keccak256(bytes(updateType));
        return lastRegisteredUpdate[key][market];
    }

    /**
     * @notice Quotes the gas fee needed to pay for the full omnichain transaction in native gas or ZRO token.
     * @param update The risk parameter update payload to be sent
     * @param options Message execution options (e.g., for sending gas to the destination)
     * @param payInLzToken Whether to return the fee in ZRO token instead of native gas
     * @return fee A `MessagingFee` struct containing the calculated gas fee
     */
    function quote(
        RiskParameterUpdate memory update,
        bytes memory options,
        bool payInLzToken
    ) public view returns (MessagingFee memory fee) {
        bytes memory payload = abi.encode(update);
        fee = _quote(update.destLzEid, payload, options, payInLzToken);
    }

    /**
     * @notice Sends a `RiskParameterUpdate` to a destination chain via LayerZero.
     * @param dstEid Destination chain endpoint ID
     * @param update The risk parameter update payload to send
     * @param options LayerZero message options; if empty, a default executor option is used
     * @param fee Messaging fee structure returned by `quote`
     * @param refundAddress Address to receive any surplus fee refunds
     * @custom:error InvalidLzSendCaller if called by any address other than this contract
     */
    function lzSend(
        uint32 dstEid,
        RiskParameterUpdate memory update,
        bytes memory options,
        MessagingFee memory fee,
        address refundAddress
    ) public payable {
        if (msg.sender != address(this)) {
            revert InvalidLzSendCaller();
        }

        bytes memory payload = abi.encode(update);
        _lzSend(dstEid, payload, options, fee, refundAddress);
    }

    /**
     * @dev Overrides OwnableUpgradeable and Ownable2StepUpgradeable to resolve
     *      the multiple inheritance ownership transfer conflict.
     */
    function transferOwnership(
        address newOwner
    ) public override(OwnableUpgradeable, Ownable2StepUpgradeable) onlyOwner {
        Ownable2StepUpgradeable.transferOwnership(newOwner);
    }

    /**
     * @dev Internal hook to finalize ownership transfer, resolving the
     *      OwnableUpgradeable and Ownable2StepUpgradeable inheritance conflict.
     */
    function _transferOwnership(address newOwner) internal override(OwnableUpgradeable, Ownable2StepUpgradeable) {
        Ownable2StepUpgradeable._transferOwnership(newOwner);
    }

    /**
     * @notice Registers an update from the Risk Oracle with a timelock.
     * @param update The risk parameter update from the Risk Oracle to register
     * @param config The risk parameter configuration for this update type containing timelock
     * @param safeForDirectExecution Whether the update is safe for direct execution
     * @param isRemoteUpdate Whether the update is a remote update to be sent cross-chain
     * @custom:event Emits UpdateRegistered with the oracle update ID, unlock time, update type, and market
     */
    function _registerUpdate(
        RiskParameterUpdate memory update,
        RiskParamConfig memory config,
        bool safeForDirectExecution,
        bool isRemoteUpdate
    ) internal {
        uint256 updateId = update.updateId;
        uint256 unlockTime = (safeForDirectExecution || isRemoteUpdate)
            ? block.timestamp
            : block.timestamp + config.timelock;

        updates[updateId] = RegisteredUpdate({
            updateId: updateId,
            unlockTime: unlockTime,
            status: UpdateStatus.Pending,
            executor: address(0),
            executedAt: 0
        });

        lastRegisteredUpdate[update.updateTypeKey][update.market] = updateId;
        emit UpdateRegistered(updateId, unlockTime, update.updateType, update.market);
    }

    /**
     * @notice Executes a validated update via the risk steward and records its execution metadata.
     *         Updates the registered update storage, last processed tracking, and emits the execution event.
     *         Preserves the unlockTime that was set during registration.
     * @param update The risk parameter update to execute
     * @param steward The risk steward contract that will process the update
     * @custom:event Emits UpdateExecuted with the oracle update ID
     */
    function _executeUpdate(RiskParameterUpdate memory update, IRiskSteward steward) internal {
        uint256 updateId = update.updateId;
        uint256 timestamp = block.timestamp;
        RegisteredUpdate storage registeredUpdate = updates[updateId];

        registeredUpdate.status = UpdateStatus.Executed;
        registeredUpdate.executor = address(msg.sender);
        registeredUpdate.executedAt = timestamp;
        lastProcessedUpdate[update.updateTypeKey][update.market] = updateId;

        steward.applyUpdate(update);
        emit UpdateExecuted(updateId);
    }

    /**
     * @notice Sends a risk parameter update to a destination chain via LayerZero and records it as sent.
     *         The update should already be registered before calling this function.
     * @param update The risk parameter update to send to the destination chain
     * @param options LayerZero message options; if empty, default executor option is used
     * @param nativeFee Native tokens supplied to cover the bridge fee (0 to use the quoted amount)
     * @custom:event Emits UpdateSentToDestination with the update ID, destination endpoint ID, update type, and market
     */
    function _sendRemoteUpdate(RiskParameterUpdate memory update, bytes memory options, uint256 nativeFee) internal {
        bytes memory option = options.length == 0
            ? OptionsBuilder.newOptions().addExecutorLzReceiveOption(1_000_000, 0)
            : options;

        MessagingFee memory fee;

        if (nativeFee == 0) {
            fee = quote(update, option, false);
        } else {
            fee = MessagingFee(nativeFee, 0);
        }

        this.lzSend{ value: fee.nativeFee }(update.destLzEid, update, option, fee, address(this));

        RegisteredUpdate storage registeredUpdate = updates[update.updateId];
        registeredUpdate.status = UpdateStatus.SENT_TO_DESTINATION;
        registeredUpdate.executor = address(msg.sender);
        registeredUpdate.executedAt = block.timestamp;

        bytes32 updateTypeKey = update.updateTypeKey;
        lastProcessedUpdate[updateTypeKey][update.market] = update.updateId;

        emit UpdateSentToDestination(update.updateId, update.destLzEid, update.updateType, update.market);
    }

    /**
     * @notice Ensures there is no other pending registered update of the same type for the same market.
     *         If a pending update exists and is expired, it is marked as expired and a new update can proceed.
     *         If a pending update exists and is not expired, the call reverts to prevent overlapping updates.
     * @param update The risk parameter update being registered
     * @custom:event Emits UpdateExpired with the ID of the previously pending update if it is found to be expired
     * @custom:error RegisteredUpdateTypeExist if there is a non‑expired pending update of the same type for the market
     */
    function _ensureNoActiveUpdate(RiskParameterUpdate memory update) internal {
        uint256 registeredUpdateId = lastRegisteredUpdate[update.updateTypeKey][update.market];
        if (registeredUpdateId == 0) return; // no prior update of this type for this market

        RegisteredUpdate storage existing = updates[registeredUpdateId];
        if (existing.status != UpdateStatus.Pending) return;

        // Check expiration
        RiskParameterUpdate memory existingUpdate = RISK_ORACLE.getUpdateById(registeredUpdateId);
        bool expired = existingUpdate.timestamp + UPDATE_EXPIRATION_TIME < block.timestamp;

        if (expired) {
            existing.status = UpdateStatus.Expired;
            emit UpdateExpired(registeredUpdateId);
            return;
        }

        // If still pending & not expired reject new update
        revert RegisteredUpdateTypeExist(registeredUpdateId);
    }

    /**
     * @notice Validates an oracle update before registration.
     * @param update The risk parameter update to validate
     * @param config The configuration for this update type
     * @custom:error UpdateAlreadyResolved if the update was already registered
     * @custom:error ConfigNotActive if the configuration for the update type is not active
     * @custom:error UpdateIsExpired if the update has expired or is not the latest for the given market and type
     * @custom:error UpdateTooFrequent if the debounce period has not passed for the given market and type
     */
    function _validateRegisterUpdate(RiskParameterUpdate memory update, RiskParamConfig storage config) internal view {
        // Check if this update was already registered
        if (updates[update.updateId].status != UpdateStatus.None) {
            revert UpdateAlreadyResolved();
        }

        // Check if config is active
        if (!config.active) {
            revert ConfigNotActive();
        }

        // Check if this is the latest update for this market and type
        RiskParameterUpdate memory latestForMarketAndType = RISK_ORACLE.getLatestUpdateByParameterAndMarket(
            update.updateType,
            update.market
        );
        if (latestForMarketAndType.updateId != update.updateId) {
            revert UpdateIsExpired();
        }

        // Check expiration
        if (update.timestamp + UPDATE_EXPIRATION_TIME < block.timestamp) {
            revert UpdateIsExpired();
        }

        // Check debounce
        uint256 lastProcessedId = lastProcessedUpdate[update.updateTypeKey][update.market];
        uint256 lastExecutionTime = updates[lastProcessedId].executedAt;
        if (lastExecutionTime != 0 && (lastExecutionTime + config.debounce > block.timestamp)) {
            revert UpdateTooFrequent();
        }
    }

    /**
     * @notice Validates a registered update before execution.
     * @param registeredUpdate The stored registered update metadata
     * @param update The risk parameter update fetched from the oracle
     * @param config The configuration for this update type
     * @custom:error ConfigNotActive if the configuration for the update type is not active
     * @custom:error InvalidRegisteredUpdate if the update was never registered
     * @custom:error UpdateAlreadyResolved if the update was already executed or rejected
     * @custom:error UpdateIsExpired if the update has expired
     * @custom:error UpdateNotUnlocked if the unlock time has not passed
     */
    function _validateExecuteUpdate(
        RegisteredUpdate memory registeredUpdate,
        RiskParameterUpdate memory update,
        RiskParamConfig storage config
    ) internal view {
        if (!config.active) {
            revert ConfigNotActive();
        }

        if (registeredUpdate.status == UpdateStatus.None) {
            revert InvalidRegisteredUpdate();
        }

        if (registeredUpdate.status != UpdateStatus.Pending) {
            revert UpdateAlreadyResolved();
        }

        if (update.timestamp + UPDATE_EXPIRATION_TIME < block.timestamp) {
            revert UpdateIsExpired();
        }

        if (block.timestamp < registeredUpdate.unlockTime) {
            revert UpdateNotUnlocked();
        }
    }

    /**
     * @notice Checks if an update has completed all conditions to be executed.
     * @param updateId The oracle update ID to query
     * @return True if the update is pending, not expired, active, and past its timelock
     */
    function _isUpdateExecutable(uint256 updateId) internal view returns (bool) {
        RegisteredUpdate storage registeredUpdate = updates[updateId];
        if (registeredUpdate.status != UpdateStatus.Pending) {
            return false;
        }

        RiskParameterUpdate memory update = RISK_ORACLE.getUpdateById(updateId);
        RiskParamConfig storage config = riskParameterConfigs[update.updateTypeKey];

        if (!config.active) {
            return false;
        }

        // Check expiration
        if (update.timestamp + UPDATE_EXPIRATION_TIME < block.timestamp) {
            return false;
        }

        // Check UnlockTime
        return block.timestamp >= registeredUpdate.unlockTime;
    }

    /**
     * @dev LayerZero message receive hook
     */
    function _lzReceive(
        Origin calldata origin,
        bytes32 guid,
        bytes calldata message,
        address executor,
        bytes calldata extraData
    ) internal virtual override {}

    /**
     * @notice Disables renounceOwnership function
     * @custom:error Throws RenounceOwnershipNotAllowed
     */
    function renounceOwnership() public pure override {
        revert RenounceOwnershipNotAllowed();
    }
}

